--
-- Table structure for table `sale_details`
--

DROP TABLE IF EXISTS `sale_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sale_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sale_id` bigint unsigned DEFAULT NULL,
  `item_number` bigint DEFAULT NULL,
  `article_id` bigint unsigned DEFAULT NULL,
  `concept` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `unit_id` bigint unsigned DEFAULT NULL,
  `referential_unit_id` bigint unsigned DEFAULT NULL,
  `value_type_id` bigint unsigned DEFAULT NULL,
  `referral_guide_series` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referral_guide_number` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `carrier_series` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `carrier_number` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_plate` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` decimal(12,4) DEFAULT NULL,
  `referential_quantity` decimal(14,6) DEFAULT NULL,
  `price_igv` decimal(12,4) DEFAULT NULL,
  `sale_value` decimal(12,4) DEFAULT NULL,
  `referential_sale_value` decimal(14,6) DEFAULT NULL,
  `inaccurate_value` decimal(12,4) DEFAULT NULL,
  `exonerated_value` decimal(12,4) DEFAULT NULL,
  `igv` decimal(12,2) DEFAULT NULL,
  `total` decimal(12,2) DEFAULT NULL,
  `total_perception` decimal(12,2) DEFAULT NULL,
  `igv_percentage` decimal(5,2) DEFAULT NULL,
  `igv_perception_percentage` decimal(5,2) DEFAULT NULL,
  `referential_convertion` decimal(12,2) DEFAULT NULL,
  `kg` decimal(12,4) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `created_at_user` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at_user` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `sale_details_sale_id_foreign` (`sale_id`) USING BTREE,
  KEY `sale_details_article_id_foreign` (`article_id`) USING BTREE,
  CONSTRAINT `sale_details_article_id_foreign` FOREIGN KEY (`article_id`) REFERENCES `articles` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `sale_details_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=257974 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
