DROP TABLE IF EXISTS `warehouse_movement_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `warehouse_movement_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `warehouse_movement_id` bigint unsigned DEFAULT NULL,
  `item_number` bigint DEFAULT NULL,
  `article_code` bigint unsigned DEFAULT NULL,
  `digit_amount` decimal(12,4) DEFAULT NULL,
  `converted_amount` decimal(12,4) DEFAULT NULL,
  `old_stock_good` decimal(12,4) DEFAULT NULL,
  `old_stock_repair` decimal(12,4) DEFAULT NULL,
  `old_stock_return` decimal(12,4) DEFAULT NULL,
  `old_stock_damaged` decimal(12,4) DEFAULT NULL,
  `old_stock_cesion` decimal(12,4) DEFAULT NULL,
  `new_stock_good` decimal(12,4) DEFAULT NULL,
  `new_stock_repair` decimal(12,4) DEFAULT NULL,
  `new_stock_return` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `new_stock_damaged` decimal(12,4) DEFAULT NULL,
  `new_stock_cesion` decimal(12,4) DEFAULT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `price` decimal(12,4) DEFAULT NULL,
  `sale_value` decimal(12,4) DEFAULT NULL,
  `exonerated_value` decimal(12,4) DEFAULT NULL,
  `inaccurate_value` decimal(12,4) DEFAULT NULL,
  `igv` decimal(12,4) DEFAULT NULL,
  `total` decimal(12,4) DEFAULT NULL,
  `igv_perception` decimal(12,4) DEFAULT NULL,
  `igv_percentage` decimal(5,2) DEFAULT NULL,
  `igv_perception_percentage` decimal(5,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `created_at_user` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at_user` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `article_num` bigint unsigned DEFAULT NULL,
  `press` int DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `warehouse_movement_details_warehouse_movement_id_foreign` (`warehouse_movement_id`) USING BTREE,
  KEY `warehouse_movement_details_article_code_foreign` (`article_code`) USING BTREE,
  CONSTRAINT `warehouse_movement_details_article_code_foreign` FOREIGN KEY (`article_code`) REFERENCES `articles` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `warehouse_movement_details_warehouse_movement_id_foreign` FOREIGN KEY (`warehouse_movement_id`) REFERENCES `warehouse_movements` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=121343 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
